package cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice;

import cn.nebulaedata.cccs.nebuwork.backend.api.agent.*;
import cn.nebulaedata.cccs.nebuwork.backend.api.workbench.WorkbenchMapper;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice.ServiceSupport.*;

@Service
public class WorkbenchServices {
    final AgentStore db;final ObjectMapper json;final AgentTasks tasks;final AgentClient engine;final WorkbenchMapper workbenches;
    final ServiceExecutions executions;final TransactionTemplate tx;final boolean available;
    public WorkbenchServices(AgentStore db,ObjectMapper json,AgentTasks tasks,AgentClient engine,WorkbenchMapper workbenches,ServiceExecutions executions,PlatformTransactionManager manager,@Value("${nebu.workbench-services.enabled:false}")boolean enabled){this.db=db;this.json=json;this.tasks=tasks;this.engine=engine;this.workbenches=workbenches;this.executions=executions;this.tx=new TransactionTemplate(manager);this.available=enabled;}
    void owned(String owner,String wb){require(workbenches.workbench(owner,wb)!=null,404,"工作台不存在");}
    ObjectNode empty(){return json.valueToTree(map("name","","description","","capabilities",Collections.emptyList(),"pages",Collections.emptyList()));}
    public Object get(String owner,String wb){owned(owner,wb);Map<String,Object> row=db.one("SELECT * FROM nw_service WHERE owner_id=? AND workbench_id=?",owner,wb);return map("available",available,"revision",row==null?0:row.get("revision"),"draft",row==null?empty():parse(json,row.get("draft_json")),"enabled",row!=null&&Boolean.TRUE.equals(row.get("enabled")),"activeReleaseId",row==null?null:row.get("active_release_id"),"platformOperations",ServiceExecutions.PLATFORM_OPERATIONS,"pageSdk",map("global","window.NebuService","ready","await NebuService.ready() => {id,projectId,releaseId,state,revision}","invoke","await NebuService.invoke(capabilityKey,input,{requestKey?}) => {id,status,result,error}; succeeded 时读取 result，异步调用使用 subscribe(id,callback)","refresh","NebuService.on(\"refresh\",refreshFunction)","state","await NebuService.state.save(newState,revision); 冲突后先重新读取 state.get()","events","NebuService.emit(eventName,data)"));}
    public Object save(String owner,String wb,JsonNode body){owned(owner,wb);fields(body,"revision","definition");JsonNode definition=validate(owner,wb,body.path("definition"),false);return tx.execute(s->{db.one("SELECT id FROM nw_workbench WHERE id=? AND owner_id=? FOR UPDATE",wb,owner);Map<String,Object> row=db.one("SELECT * FROM nw_service WHERE owner_id=? AND workbench_id=? FOR UPDATE",owner,wb);if(row!=null&&body.path("revision").asLong(-1)+1==number(row,"revision")&&fingerprint(json,definition).equals(fingerprint(json,parse(json,row.get("draft_json")))))return get(owner,wb);require(body.path("revision").asLong(-1)==(row==null?0:number(row,"revision")),409,"服务草稿已变化，请重新加载");if(row==null)db.update("INSERT INTO nw_service(owner_id,workbench_id,revision,draft_json) VALUES(?,?,1,?)",owner,wb,definition.toString());else db.update("UPDATE nw_service SET draft_json=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE owner_id=? AND workbench_id=?",definition.toString(),owner,wb);return get(owner,wb);});}
    JsonNode validate(String owner,String wb,JsonNode d,boolean publish){fields(d,"name","description","capabilities","pages");require(d.toString().length()<=1000000,413,"服务定义超过 1 MiB");text(d,"name",200);require(d.path("capabilities").isArray()&&d.path("pages").isArray()&&d.path("capabilities").size()<=100&&d.path("pages").size()<=50,422,"需要有限的能力和页面列表");Set<String> keys=new HashSet<>();
        for(JsonNode c:d.path("capabilities")){fields(c,"key","name","description","inputSchema","outputSchema","binding","projectIds","channels","pageKey");String key=text(c,"key",80);require(key.matches(KEY)&&keys.add(key),422,"能力标识无效或重复");text(c,"name",200);for(String field:Arrays.asList("inputSchema","outputSchema")){JsonNode schema=c.path(field);require(schema.isObject()||schema.isBoolean(),422,"需要输入和输出 Schema");localReferences(schema);try{com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V7).getSchema(schema);}catch(Exception e){throw new cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException(422,"Schema 无效");}}
            require(c.path("projectIds").isArray()&&c.path("projectIds").size()>0&&c.path("projectIds").size()<=100,422,"能力必须明确指定授权项目");for(JsonNode p:c.path("projectIds"))project(owner,wb,p.asText(),false);
            require(c.path("channels").isObject(),422,"需要 API、MCP、页面开放配置");fields(c.path("channels"),"api","mcp","page");for(JsonNode value:c.path("channels"))require(value.isBoolean(),422,"入口开关必须为布尔值");
            executions.validate(owner,wb,c,publish);
        }
        Set<String> pageKeys=new HashSet<>();for(JsonNode p:d.path("pages")){fields(p,"key","name","assetId","capabilities","refreshSeconds","projectIds");String key=text(p,"key",80);require(key.matches(KEY)&&pageKeys.add(key),422,"页面标识无效或重复");text(p,"name",200);asset(owner,wb,text(p,"assetId",128));if(p.has("projectIds")){require(p.path("projectIds").isArray()&&p.path("projectIds").size()>0&&p.path("projectIds").size()<=100,422,"页面必须指定有限的授权项目");Set<String> seen=new HashSet<>();for(JsonNode ref:p.path("projectIds")){require(ref.isTextual()&&seen.add(ref.asText()),422,"页面授权项目无效或重复");project(owner,wb,ref.asText(),false);}}require(p.path("capabilities").isArray(),422,"页面需要声明可调用能力");for(JsonNode c:p.path("capabilities")){require(keys.contains(c.asText()),422,"页面引用未知能力");require(item(d,"capabilities",c.asText()).path("channels").path("page").asBoolean(),422,"页面能力尚未开放");}if(p.has("projectIds"))for(JsonNode project:p.path("projectIds"))for(JsonNode c:p.path("capabilities"))require(contains(item(d,"capabilities",c.asText()).path("projectIds"),project.asText()),422,"页面项目未获所选能力授权");if(p.has("refreshSeconds"))require(p.path("refreshSeconds").isInt()&&(p.path("refreshSeconds").asInt()==0||p.path("refreshSeconds").asInt()>=5&&p.path("refreshSeconds").asInt()<=3600),422,"刷新周期为 0 或 5–3600 秒");}
        for(JsonNode c:d.path("capabilities"))if(c.hasNonNull("pageKey")){require(pageKeys.contains(c.path("pageKey").asText()),422,"能力关联页面不存在");require(contains(item(d,"pages",c.path("pageKey").asText()).path("capabilities"),c.path("key").asText()),422,"关联页面未声明此能力");}
        require(!publish||!keys.isEmpty()||!pageKeys.isEmpty(),422,"空服务不能发布");return d.deepCopy();
    }
    public Object publish(String owner,String wb,long revision){owned(owner,wb);return tx.execute(s->{Map<String,Object> row=db.one("SELECT * FROM nw_service WHERE owner_id=? AND workbench_id=? FOR UPDATE",owner,wb);Map<String,Object> existing=db.one("SELECT * FROM nw_service_release WHERE owner_id=? AND workbench_id=? AND source_revision=? AND preview=FALSE",owner,wb,revision);if(existing!=null)return releaseView(existing);require(row!=null&&number(row,"revision")==revision,409,"服务草稿已变化");JsonNode definition=validate(owner,wb,parse(json,row.get("draft_json")),true);ObjectNode execution=json.createObjectNode();for(JsonNode c:definition.path("capabilities"))execution.set(c.path("key").asText(),executions.capture(owner,wb,c));Map<String,Object> count=db.one("SELECT COALESCE(MAX(version),0) AS total FROM nw_service_release WHERE owner_id=? AND workbench_id=? AND preview=FALSE",owner,wb);String release=id();db.update("INSERT INTO nw_service_release(id,owner_id,workbench_id,version,source_revision,definition_json,execution_json) VALUES(?,?,?,?,?,?,?)",release,owner,wb,number(count,"total")+1,revision,definition.toString(),execution.toString());db.update("UPDATE nw_service SET active_release_id=?,enabled=TRUE WHERE owner_id=? AND workbench_id=?",release,owner,wb);return releaseView(release(owner,wb,release));});}
    public Object preview(String owner,String wb,long revision){owned(owner,wb);return tx.execute(s->{Map<String,Object> row=db.one("SELECT * FROM nw_service WHERE owner_id=? AND workbench_id=? FOR UPDATE",owner,wb);require(row!=null&&number(row,"revision")==revision,409,"请先保存当前草稿");Map<String,Object> prior=db.one("SELECT * FROM nw_service_release WHERE owner_id=? AND workbench_id=? AND source_revision=? AND preview=TRUE",owner,wb,revision);if(prior!=null)return releaseView(prior);JsonNode definition=validate(owner,wb,parse(json,row.get("draft_json")),true);ObjectNode execution=json.createObjectNode();for(JsonNode c:definition.path("capabilities"))execution.set(c.path("key").asText(),executions.capture(owner,wb,c));String release=id();db.update("INSERT INTO nw_service_release(id,owner_id,workbench_id,version,source_revision,definition_json,execution_json,preview) VALUES(?,?,?,?,?,?,?,TRUE)",release,owner,wb,-revision-1,revision,definition.toString(),execution.toString());return releaseView(release(owner,wb,release));});}
    public List<Object> releases(String owner,String wb){owned(owner,wb);List<Object> out=new ArrayList<>();for(Map<String,Object> r:db.rows("SELECT * FROM nw_service_release WHERE owner_id=? AND workbench_id=? AND preview=FALSE ORDER BY version DESC",owner,wb))out.add(releaseView(r));return out;}
    Object releaseView(Map<String,Object> r){return map("id",r.get("id"),"version",r.get("version"),"sourceRevision",r.get("source_revision"),"preview",r.get("preview"),"definition",parse(json,r.get("definition_json")),"createdAt",Objects.toString(r.get("created_at"),""));}
    public Object change(String owner,String wb,String action,JsonNode body){owned(owner,wb);return tx.execute(s->{Map<String,Object> row=db.one("SELECT * FROM nw_service WHERE owner_id=? AND workbench_id=? FOR UPDATE",owner,wb);require(row!=null&&number(row,"revision")==body.path("revision").asLong(-1),409,"服务配置已变化");if("activate".equals(action)){String release=text(body,"releaseId",128);require(!Boolean.TRUE.equals(release(owner,wb,release).get("preview")),403,"草稿预览不能激活为正式服务");db.update("UPDATE nw_service SET active_release_id=?,enabled=TRUE,revision=revision+1 WHERE owner_id=? AND workbench_id=?",release,owner,wb);}else{require("disable".equals(action),422,"未知服务操作");db.update("UPDATE nw_service SET enabled=FALSE,revision=revision+1 WHERE owner_id=? AND workbench_id=?",owner,wb);}return get(owner,wb);});}
    Map<String,Object> release(String owner,String wb,String release){Map<String,Object> r=db.one("SELECT * FROM nw_service_release WHERE id=? AND owner_id=? AND workbench_id=?",release,owner,wb);require(r!=null,404,"服务版本不存在");return r;}
    Map<String,Object> active(ServiceAccess.Principal p,String wb,String release){require(available,503,"工作台服务功能尚未启用");owned(p.owner,wb);require(p.browser||p.workbench.equals(wb),403,"应用未授权此工作台");Map<String,Object> explicit=release==null||release.isEmpty()?null:release(p.owner,wb,release);if(explicit!=null&&Boolean.TRUE.equals(explicit.get("preview"))){require(p.browser,403,"草稿预览未公开发布");return explicit;}Map<String,Object> row=db.one("SELECT * FROM nw_service WHERE owner_id=? AND workbench_id=?",p.owner,wb);require(row!=null&&Boolean.TRUE.equals(row.get("enabled")),409,"服务尚未发布或已停用");return explicit==null?release(p.owner,wb,str(row,"active_release_id")):explicit;}
    Map<String,Object> project(String owner,String wb,String project,boolean write){Map<String,Object> p=tasks.project(owner,project,write);require(wb.equals(str(p,"workbench_id")),403,"项目不属于此工作台");return p;}
    public Object assetAdd(String owner,String wb,JsonNode body){return assetAdd(owner,wb,body,null);}
    public Object assetAdd(String owner,String wb,JsonNode body,JsonNode provenance){
        owned(owner,wb);fields(body,"html","projectId","artifactId","version","entryPath","resources");
        String html;JsonNode source=json.createObjectNode();boolean bundle=body.has("entryPath");
        require(!(body.has("html")&&body.has("artifactId"))&&(!body.has("resources")||bundle),422,"请选择一种 HTML 资产来源");
        if(body.has("artifactId")){
            String project=text(body,"projectId",128);project(owner,wb,project,false);String artifact=text(body,"artifactId",128);
            require(body.path("version").isIntegralNumber()&&body.path("version").canConvertToInt()&&body.path("version").asInt()>0,422,"必须固定成果版本");int version=body.path("version").asInt();
            if(bundle){
                require(engine.get(owner,project,"/v1/capabilities").path("htmlArtifactBundles").asBoolean(),409,"当前引擎不支持 HTML 配套资源发布，请先升级引擎 API");
                ObjectNode input=((ObjectNode)body).deepCopy();input.remove("projectId");
                JsonNode result=engine.post(owner,project,"/v1/projects/"+AgentClient.segment(project)+"/html-bundles",input,"html-bundle:"+fingerprint(json,input));
                require(result.path("html").isTextual()&&result.path("source").isObject(),502,"页面打包结果无效");html=result.path("html").asText();source=result.path("source").deepCopy();
                require(hash(html).equals(result.path("sha256").asText())&&project.equals(source.path("projectId").asText()),502,"页面打包结果校验失败");
            }else{
                JsonNode metadata=engine.get(owner,project,"/v1/artifacts/"+AgentClient.segment(artifact)+"?version="+version);
                require(metadata.path("size").asLong()>0&&metadata.path("size").asLong()<=2*1024*1024,413,"页面须小于 2 MiB");
                require(project.equals(metadata.path("projectId").asText())&&metadata.path("version").asInt()==version,404,"成果版本不属于当前项目");
                html=new String(engine.contentBytes(owner,project,artifact,version),StandardCharsets.UTF_8);
                require(hash(html).equals(metadata.path("sha256").asText()),502,"HTML 产物校验失败");
                source=json.valueToTree(map("projectId",project,"artifactId",artifact,"version",version,"sha256",metadata.path("sha256")));
            }
        }else{require(!bundle,422,"资源包必须指定入口成果");html=text(body,"html",2*1024*1024);}
        require(html.getBytes(StandardCharsets.UTF_8).length<=(bundle?32:2)*1024*1024&&!html.contains("\u0000"),413,bundle?"打包页面须小于 32 MiB":"页面须为小于 2 MiB 的 HTML");
        if(provenance!=null)((ObjectNode)source).set("task",provenance);
        String hash=hash(html),asset="sa-"+hash(owner+":"+wb+":"+hash+":"+fingerprint(json,source));
        db.update("INSERT INTO nw_service_asset(id,owner_id,workbench_id,content_hash,html,source_json) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",asset,owner,wb,hash,html,source.toString());
        return map("id",asset,"sha256",hash,"size",html.getBytes(StandardCharsets.UTF_8).length,"source",source);
    }
    public Object assetView(String owner,String wb,String id){owned(owner,wb);Map<String,Object> a=asset(owner,wb,id);String html=str(a,"html");return map("id",id,"html",html,"sha256",a.get("content_hash"),"size",html.getBytes(StandardCharsets.UTF_8).length,"source",parse(json,a.get("source_json")));}
    Map<String,Object> asset(String owner,String wb,String id){Map<String,Object> a=db.one("SELECT * FROM nw_service_asset WHERE id=? AND owner_id=? AND workbench_id=?",id,owner,wb);require(a!=null,404,"页面资产不存在");return a;}
    public Object manifest(ServiceAccess.Principal p,String wb,String release){Map<String,Object> r=active(p,wb,release);ObjectNode d=(ObjectNode)parse(json,r.get("definition_json"));ArrayNode capabilities=json.createArrayNode(),pages=json.createArrayNode();for(JsonNode c:d.path("capabilities"))if(p.browser||contains(p.scope.path("capabilities"),c.path("key").asText())){ObjectNode safe=c.deepCopy();safe.remove("binding");safe.remove("projectIds");capabilities.add(safe);}for(JsonNode page:d.path("pages"))if(p.browser||contains(p.scope.path("pages"),page.path("key").asText())){ObjectNode safe=page.deepCopy();safe.remove("assetId");if(!p.browser&&safe.has("projectIds")){ArrayNode allowed=json.createArrayNode();for(JsonNode ref:safe.path("projectIds"))if(contains(p.scope.path("projects"),ref.asText()))allowed.add(ref);safe.set("projectIds",allowed);}pages.add(safe);}List<Object> projects=new ArrayList<>();Set<String> projectIds=new HashSet<>();for(JsonNode c:d.path("capabilities"))if(p.browser||contains(p.scope.path("capabilities"),c.path("key").asText()))for(JsonNode project:c.path("projectIds"))if(p.browser||contains(p.scope.path("projects"),project.asText()))projectIds.add(project.asText());for(JsonNode page:d.path("pages"))if(p.browser||contains(p.scope.path("pages"),page.path("key").asText()))for(JsonNode project:page.path("projectIds"))if(p.browser||contains(p.scope.path("projects"),project.asText()))projectIds.add(project.asText());for(String id:projectIds){Map<String,Object> project=db.one("SELECT id,name,status FROM nw_project WHERE id=? AND owner_id=? AND workbench_id=?",id,p.owner,wb);if(project!=null)projects.add(project);}return map("projects",projects,"workbenchId",wb,"releaseId",r.get("id"),"version",r.get("version"),"name",d.path("name"),"description",d.path("description"),"capabilities",capabilities,"pages",pages);}
    public Object openapi(ServiceAccess.Principal p,String wb,String release){
        JsonNode manifest=json.valueToTree(manifest(p,wb,release));ObjectNode paths=json.createObjectNode();
        for(JsonNode c:manifest.path("capabilities"))if(c.path("channels").path("api").asBoolean()){
            String route="/api/workbench-services/"+wb+"/capabilities/"+c.path("key").asText()+"/invoke";
            ObjectNode properties=json.createObjectNode();properties.putObject("projectId").put("type","string");properties.set("input",c.path("inputSchema"));properties.putObject("releaseId").put("type","string");
            Object operationSchema=map("type","object","required",Arrays.asList("operationId","status"),"properties",map("operationId",map("type","string"),"status",map("type","string","enum",Arrays.asList("pending","dispatching","running","waiting_input","interrupted","succeeded","failed","cancelled")),"result",map("anyOf",Arrays.asList(c.path("outputSchema"),map("type","null")))));
            Object responseBody=map("application/json",map("schema",map("type","object","properties",map("code",map("type","integer"),"data",operationSchema))));
            paths.set(route,json.valueToTree(map("post",map("operationId",c.path("key"),"summary",c.path("name"),"parameters",Collections.singletonList(map("in","header","name","Idempotency-Key","required",true,"schema",map("type","string"))),"security",Collections.singletonList(map("serviceBearer",Collections.emptyList())),"requestBody",map("required",true,"content",map("application/json",map("schema",map("type","object","required",Arrays.asList("projectId","input"),"properties",properties)))),"responses",map("200",map("description","执行完成；仍需检查 data.status","content",responseBody),"202",map("description","已受理异步操作","content",responseBody)),"x-result-schema",c.path("outputSchema")))));
        }
        return map("openapi","3.1.0","jsonSchemaDialect","http://json-schema.org/draft-07/schema#","info",map("title",manifest.path("name"),"version",manifest.path("version").asText()),"paths",paths,"components",map("securitySchemes",map("serviceBearer",map("type","http","scheme","bearer"))));
    }
}
